-- public.farm_refusal(p_world uuid, p_uid uuid, p_action text, p_target jsonb)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.farm_refusal(p_world uuid, p_uid uuid, p_action text, p_target jsonb)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
declare tx int; ty int; here int; c crop; it item; v_r int; v_why text; v_bed int; v_lvl int;
begin
  tx := (p_target->>'x')::int; ty := (p_target->>'y')::int;
  here := land_tile(p_world, tx, ty);
  -- Anything that reads a crop reads it up to date.
  perform crop_settle(p_world, tx, ty);
  select * into c from crop cr where cr.world_id = p_world and cr.x = tx and cr.y = ty;
  -- The garden bed of the storey you stand on (`bed_level_of`), or the field; a crop on another storey is none of this job's.
  v_lvl := farm_level(p_world, p_uid);
  v_bed := bed_level_of(p_world, p_uid, tx, ty);
  if c.id is not null and c.level is distinct from v_bed and p_action <> 'plant_seed' then c := null; end if;

  if p_action = 'till' then
    -- In a building, only a glasshouse's ground, where no floor is planned on it (`glass_till_refusal`).
    if building_at(p_world, tx, ty) is not null then
      v_why := glass_till_refusal(p_world, tx, ty);
      if v_why is not null then return v_why; end if;
    elsif not tillable(here) then return not_tillable_said(); end if;
    if land_height(p_world, tx, ty) < 0 or land_height(p_world, tx + 1, ty) < 0
       or land_height(p_world, tx + 1, ty + 1) < 0 or land_height(p_world, tx, ty + 1) < 0 then
      return 'Not under water.';
    end if;
    if tile_slope(p_world, tx, ty) > 20 then return 'Too steep: slope over ' || metres(20) || ' m.'; end if;
  elsif p_action = 'plant_moss' then
    -- In the browser's words and order (actions.ts, `plant_moss`).
    if here <> tile_id('Dirt') then return 'Needs a dirt tile.'; end if;
    if has_water(p_world, tx, ty) then return 'Not under water.'; end if;
    if pack_count(p_world, p_uid, 'moss') < moss_plant() then
      return 'Need ' || moss_plant() || ' moss; have ' || pack_count(p_world, p_uid, 'moss') || '.';
    end if;
    -- Piers: nor under a building, which a tile on piers is (`underBuilding`).
    if under_building(p_world, tx, ty) is not null then return under_building(p_world, tx, ty); end if;
  elsif p_action = 'plant_grass' then
    -- In the browser's words and order (actions.ts, `plant_grass`), as moss is planted.
    if here <> tile_id('Dirt') then return 'Needs a dirt tile.'; end if;
    if has_water(p_world, tx, ty) then return 'Not under water.'; end if;
    if pack_count(p_world, p_uid, 'mixed_grass') < grass_plant() then
      return 'Need ' || grass_plant() || ' mixed grass; have ' || pack_count(p_world, p_uid, 'mixed_grass') || '.';
    end if;
    if under_building(p_world, tx, ty) is not null then return under_building(p_world, tx, ty); end if;
  elsif p_action = 'plant_seed' then
    if v_bed is null and here <> tile_id('Field') then return 'Needs a tilled field.'; end if;
    -- Covered, or a crop on the tile already, on this storey or another (`bed_sow_refusal`).
    v_why := bed_sow_refusal(p_world, tx, ty, v_bed);
    if v_why is not null then return v_why; end if;
    select * into it from item
      where id = target_item(p_target) and world_id = p_world
        and holder = 'player' and holder_uid = p_uid;
    if not found or not exists (select 1 from crop_def where seed = it.def) then
      return 'Choose a seed.';
    end if;
  elsif p_action = 'tend_crop' then
    if c.id is null then return 'No crop there.'; end if;
    if c.stage >= crop_ripe() then return 'Ripe: harvest it.'; end if;
    if c.tended_now then return 'Already tended at this growth stage.'; end if;
  elsif p_action = 'harvest_crop' then
    if c.id is null then return 'No crop there.'; end if;
    if c.stage < crop_ripe() then
      return 'Not ripe: ' || crop_stage_name(c.stage) || '.';
    end if;
  elsif p_action = 'clear_field' then
    -- A garden bed is pulled up, and only with something on it.
    if v_bed is not null then
      if c.id is null then return 'No crop there.'; end if;
    elsif here <> tile_id('Field') then return 'There is no field there.'; end if;
  elsif p_action = 'sow_patch' then
    if pk(p_world, p_uid, 'sow_patch', 0) <= 0 then return 'Needs perk: Sow a Patch (Farmer).'; end if;
    select * into it from item
      where id = target_item(p_target) and world_id = p_world
        and holder = 'player' and holder_uid = p_uid;
    if not found or not exists (select 1 from crop_def where seed = it.def) then
      return 'Choose a seed.';
    end if;
    v_r := floor(pk(p_world, p_uid, 'sow_patch', 0))::int;
    if not exists (select 1 from generate_series(ty - v_r, ty + v_r) gy, generate_series(tx - v_r, tx + v_r) gx
                    where patch_sowable(p_world, v_lvl, gx, gy)) then
      return 'No empty field in the patch.';
    end if;
  elsif p_action = 'tend_patch' then
    if pk(p_world, p_uid, 'tend_patch', 0) <= 0 then return 'Needs perk: Tend a Patch (Farmer).'; end if;
    v_r := floor(pk(p_world, p_uid, 'tend_patch', 0))::int;
    perform crops_settle(p_world, tx + 0.5, ty + 0.5, v_r);
    if not exists (select 1 from crop cr
                    where cr.world_id = p_world and cr.x between tx - v_r and tx + v_r and cr.y between ty - v_r and ty + v_r
                      and coalesce(cr.level, 0) = v_lvl and cr.stage < crop_ripe() and not cr.tended_now) then
      return 'Nothing in the patch needs tending.';
    end if;
  elsif p_action = 'harvest_patch' then
    if pk(p_world, p_uid, 'harvest_patch', 0) <= 0 then return 'Needs perk: Harvest a Patch (Farmer).'; end if;
    v_r := floor(pk(p_world, p_uid, 'harvest_patch', 0))::int;
    perform crops_settle(p_world, tx + 0.5, ty + 0.5, v_r);
    if not exists (select 1 from crop cr
                    where cr.world_id = p_world and cr.x between tx - v_r and tx + v_r and cr.y between ty - v_r and ty + v_r
                      and coalesce(cr.level, 0) = v_lvl and cr.stage >= crop_ripe()) then
      return 'Nothing in the patch is ripe.';
    end if;
  end if;
  return null;
end $function$
